def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
        old_char = board[row][col]
        if old_char == 'W':
            new_char = 'p'
        else:
            new_char = 'W'
        board[row] = board[row][:col] + new_char + board[row][col+1:]
    else:
        raise ValueError("Action must be a tuple of row and column")
    return ["".join(row) for row in board]
